<?php require_once __DIR__.'/_helpers.php';$r=pdata('reports');$c=pdata('chws');$v=pdata('visits');$ref=pdata('referrals');$edu=pdata('education-sessions');$stats=[['Active CHWs',count(array_filter($c,fn($x)=>$x['status']==='active'))],['Reports submitted',count(array_filter($r,fn($x)=>$x['status']!=='DRAFT'))],['Pending review',count(array_filter($r,fn($x)=>in_array($x['status'],['SUBMITTED','UNDER_REVIEW'])))],['Households visited',count($v)],['Referrals',count($ref)],['Education sessions',count($edu)]];?>
<section><div class="welcome"><div><span class="eyebrow"><?=htmlspecialchars($roleLabels[$user['role']]??$user['role'])?></span><h2>Community health operations overview</h2><p>Monitor reporting, community activity and follow-up performance.</p></div><div class="welcome-actions"><a class="primary" href="?page=reports">View reports</a><?php if($user['role']==='chw'):?><a class="primary" href="?page=report-create">＋ New report</a><?php endif;?></div></div><div class="notice"><span>i</span><div><strong>Prototype environment</strong><p>All data is fictional and loaded from local JSON. Future authentication and authorization must be enforced server-side.</p></div></div><div class="stat-grid"><?php foreach($stats as $s):?><div class="stat-card"><span><?=htmlspecialchars($s[0])?></span><strong><?=$s[1]?></strong><small>Demo data</small></div><?php endforeach;?></div><div class="grid-2"><div class="panel"><div class="panel-head"><div><h3>Report status</h3><p>Current workflow</p></div></div><div class="bars"><?php foreach(['APPROVED','SUBMITTED','UNDER_REVIEW','REJECTED','CORRECTION_REQUIRED','DRAFT'] as $s):$n=count(array_filter($r,fn($x)=>$x['status']===$s));$w=max(5,$n/max(1,count($r))*100);?><div class="bar-row"><span><?=htmlspecialchars(str_replace('_',' ',$s))?></span><div><i style="width:<?=$w?>%"></i></div><b><?=$n?></b></div><?php endforeach;?></div></div><div class="panel"><div class="panel-head"><div><h3>Referral status</h3><p>Current referral queue</p></div></div><div class="mini-list"><?php foreach(['Pending','Referred','Received','In Progress','Completed','Follow-up Required'] as $s):?><div><span class="status-dot"></span><span><?=htmlspecialchars($s)?></span><strong><?=count(array_filter($ref,fn($x)=>$x['status']===$s))?></strong></div><?php endforeach;?></div></div></div><div class="panel"><div class="panel-head"><div><h3>Recent reports</h3><p>Latest seeded submissions</p></div></div><?php ptable(array_slice($r,0,6),['id','chw_id','period','submitted_at','status']);?></div></section>
